import React from 'react';
import { Link } from 'react-router-dom';
import { Bed, Bath, Car, Maximize, MapPin, Heart } from 'lucide-react';
import { formatPrice, STATUS_LABELS } from '../data/mockData';
import './PropertyCard.css';

export default function PropertyCard({ property, onWishlist, isWishlisted }) {
  const status = STATUS_LABELS[property.status] || STATUS_LABELS.available;

  return (
    <div className="property-card">
      <Link to={`/listings/${property.id}`} className="property-card-image">
        <img src={property.images[0]} alt={property.title} loading="lazy" />
        <span className={`badge ${status.cls} status-badge`}>{status.label}</span>
        <span className="listing-type-badge">{property.listingType === 'rental' ? 'To Let' : 'For Sale'}</span>
        {onWishlist && (
          <button
            className={`wishlist-btn ${isWishlisted ? 'active' : ''}`}
            onClick={(e) => { e.preventDefault(); onWishlist(property.id); }}
            title={isWishlisted ? 'Remove from wishlist' : 'Save to wishlist'}
          >
            <Heart size={16} fill={isWishlisted ? 'currentColor' : 'none'} />
          </button>
        )}
      </Link>
      <div className="property-card-body">
        <div className="property-price">{formatPrice(property.price, property.listingType)}</div>
        <Link to={`/listings/${property.id}`}>
          <h3 className="property-title">{property.title}</h3>
        </Link>
        <p className="property-location">
          <MapPin size={13} /> {property.suburb}, {property.city}
        </p>
        <div className="property-specs">
          {property.bedrooms != null && <span><Bed size={14} /> {property.bedrooms}</span>}
          {property.bathrooms != null && <span><Bath size={14} /> {property.bathrooms}</span>}
          {property.garages != null && <span><Car size={14} /> {property.garages}</span>}
          {property.floorSize && <span><Maximize size={14} /> {property.floorSize}m²</span>}
          {!property.floorSize && property.standSize && <span><Maximize size={14} /> {property.standSize}m²</span>}
        </div>
        <div className="property-card-footer">
          <div className="agent-mini">
            <img src={property.agentPhoto} alt={property.agentName} />
            <span>{property.agentName}</span>
          </div>
          <Link to={`/listings/${property.id}`} className="btn btn-primary btn-sm">View</Link>
        </div>
      </div>
    </div>
  );
}
